  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `sku_id` bigint unsigned NOT NULL,
  `status` enum('pending','confirmed','deleted') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pending',
  `before_data` json NOT NULL,
  `after_data` json NOT NULL,
  `changed_fields` json NOT NULL,
  `created_by` bigint unsigned NOT NULL,
  `created_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updated_at` datetime(3) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `product_edit_requests_sku_id_created_at_idx` (`sku_id`,`created_at`),
  KEY `product_edit_requests_created_by_created_at_idx` (`created_by`,`created_at`),
  KEY `product_edit_requests_status_created_at_idx` (`status`,`created_at`),
  CONSTRAINT `product_edit_requests_created_by_fkey` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `product_edit_requests_sku_id_fkey` FOREIGN KEY (`sku_id`) REFERENCES `skus` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=537 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table: role_options
DROP TABLE IF EXISTS `role_options`;
CREATE TABLE `role_options` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `code` enum('employee','admin','system_admin') COLLATE utf8mb4_unicode_ci NOT NULL,
  `name` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `status` tinyint NOT NULL DEFAULT '1',
  `sort` int NOT NULL DEFAULT '0',
  `created_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updated_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  PRIMARY KEY (`id`),
  UNIQUE KEY `role_options_code_key` (`code`)
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table: shelves
DROP TABLE IF EXISTS `shelves`;
CREATE TABLE `shelves` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `shelf_code` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `name` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `status` tinyint NOT NULL DEFAULT '1',
  `created_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updated_at` datetime(3) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `shelves_shelf_code_key` (`shelf_code`)
) ENGINE=InnoDB AUTO_INCREMENT=51 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table: shops
DROP TABLE IF EXISTS `shops`;
CREATE TABLE `shops` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL,
  `status` tinyint NOT NULL DEFAULT '1',
  `created_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updated_at` datetime(3) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `shops_name_key` (`name`)
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table: sku_types
DROP TABLE IF EXISTS `sku_types`;
CREATE TABLE `sku_types` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL,
  `status` tinyint NOT NULL DEFAULT '1',
  `created_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updated_at` datetime(3) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `sku_types_name_key` (`name`)
) ENGINE=InnoDB AUTO_INCREMENT=7 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table: skus
DROP TABLE IF EXISTS `skus`;
CREATE TABLE `skus` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `product_id` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `sku` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL,
  `erp_sku` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `asin` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `fnsku` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `fbm_sku` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `model` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `brand` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `type` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `color` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `shop` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `remark` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `status` tinyint NOT NULL DEFAULT '1',
  `created_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updated_at` datetime(3) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `skus_sku_key` (`sku`),
  UNIQUE KEY `skus_product_id_key` (`product_id`)
) ENGINE=InnoDB AUTO_INCREMENT=1548 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table: stock_movements
DROP TABLE IF EXISTS `stock_movements`;
CREATE TABLE `stock_movements` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `movement_type` enum('inbound','outbound','stocktake_gain','stocktake_loss','adjust') COLLATE utf8mb4_unicode_ci NOT NULL,
  `ref_type` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL,
  `ref_id` bigint unsigned NOT NULL,
  `box_id` bigint unsigned NOT NULL,
  `sku_id` bigint unsigned NOT NULL,
  `qty_delta` int NOT NULL,
  `operator_id` bigint unsigned NOT NULL,
  `created_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (`id`),
  KEY `stock_movements_sku_id_created_at_idx` (`sku_id`,`created_at`),
  KEY `stock_movements_box_id_created_at_idx` (`box_id`,`created_at`),
  KEY `stock_movements_operator_id_fkey` (`operator_id`),
  CONSTRAINT `stock_movements_box_id_fkey` FOREIGN KEY (`box_id`) REFERENCES `boxes` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `stock_movements_operator_id_fkey` FOREIGN KEY (`operator_id`) REFERENCES `users` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `stock_movements_sku_id_fkey` FOREIGN KEY (`sku_id`) REFERENCES `skus` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=1533 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table: stocktake_planner_tasks
DROP TABLE IF EXISTS `stocktake_planner_tasks`;
CREATE TABLE `stocktake_planner_tasks` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `task_no` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `planned_date` date NOT NULL,
  `shelf_id` bigint unsigned NOT NULL,
  `status` enum('pending','confirming','confirmed','canceled') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pending',
  `created_by` bigint unsigned NOT NULL,
  `confirmed_by` bigint unsigned DEFAULT NULL,
  `confirmed_at` datetime(3) DEFAULT NULL,
  `created_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updated_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  PRIMARY KEY (`id`),
  UNIQUE KEY `stocktake_planner_tasks_task_no_key` (`task_no`),
  KEY `stocktake_planner_tasks_planned_date_idx` (`planned_date`),
  KEY `stocktake_planner_tasks_shelf_id_idx` (`shelf_id`),
  KEY `stocktake_planner_tasks_created_by_fkey` (`created_by`),
  KEY `stocktake_planner_tasks_confirmed_by_fkey` (`confirmed_by`),
  CONSTRAINT `stocktake_planner_tasks_confirmed_by_fkey` FOREIGN KEY (`confirmed_by`) REFERENCES `users` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `stocktake_planner_tasks_created_by_fkey` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `stocktake_planner_tasks_shelf_id_fkey` FOREIGN KEY (`shelf_id`) REFERENCES `shelves` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=82 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table: stocktake_records
DROP TABLE IF EXISTS `stocktake_records`;
CREATE TABLE `stocktake_records` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `task_id` bigint unsigned NOT NULL,
  `box_id` bigint unsigned NOT NULL,
  `sku_id` bigint unsigned NOT NULL,
  `system_qty` int NOT NULL,
  `counted_qty` int NOT NULL,
  `diff_qty` int NOT NULL,
  `created_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (`id`),
  KEY `stocktake_records_task_id_fkey` (`task_id`),
  KEY `stocktake_records_box_id_fkey` (`box_id`),
  KEY `stocktake_records_sku_id_fkey` (`sku_id`),
  CONSTRAINT `stocktake_records_box_id_fkey` FOREIGN KEY (`box_id`) REFERENCES `boxes` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `stocktake_records_sku_id_fkey` FOREIGN KEY (`sku_id`) REFERENCES `skus` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `stocktake_records_task_id_fkey` FOREIGN KEY (`task_id`) REFERENCES `stocktake_tasks` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table: stocktake_tasks
DROP TABLE IF EXISTS `stocktake_tasks`;
CREATE TABLE `stocktake_tasks` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `task_no` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `scope_type` enum('sample') COLLATE utf8mb4_unicode_ci NOT NULL,
